def source_pages(n):
 s=(R/f'reports/literature/article-{n:02}-full.txt').read_text(encoding='utf-8').replace('\x00','-')
 return {int(x.split(' ===')[0]):x.split('===',1)[1] for x in s.split('=== PDF PAGE ')[1:]}
for n,obj in D.items():
 pages=source_pages(n);found={};continuations=[]
 for page,text in pages.items():
  lines=text.splitlines()
  for j,line in enumerate(lines):
   m=re.match(r'^(?:Fig\.|Figure)\s+([A-Z]?\.?\d+)\.',line)
   if not m:continue
   id=m[1]
   if '(continued)' in line:
    continuations.append((id,page,line));continue
   if id in found:continue
   cap=' '.join(lines[j:j+3]).strip()
   found[id]=(page,cap)
 figures=[]
 for id,en,fa,den,dfa in F[n]:
  if id not in found:raise ValueError((n,id,'caption not found'))
  page,cap=found[id]
  figures.append(dict(id=id,page=page,caption=dict(en=cap,fa=fa),explanation=dict(en=en,fa=fa),data=dict(en=den,fa=dfa)))
 for id,page,cap in continuations:
  source=next(f for f in figures if f['id']==id)
  figures.append(dict(id=f'{id}-continued-p{page}',page=page,caption=dict(en=f'Figure{id}, continued source page',fa=f'ادامه شکل{id} درصفحه{page}'),explanation=source['explanation'],data=dict(en=f'Continuation of Figure{id}; read with its preceding page and the figure-specific counts above.',fa=f'ادامه شکل{id}؛همراه صفحه پیشین وتعدادهای مشخص همان شکل خوانده شود.')))
